                        break;
                    case 38:
                        self.adjustDate('subtract', 7);
                        break;
                    case 39:
                        self.adjustDate('add', 1);
                        break;
                    case 40:
                        self.adjustDate('add', 7);
                        break;
                    case 8:
                    case 46:
                        self.setDate(null);
                        break;
                }"
    }
  ],
  "expected_accessibility_effect": "Pressing Tab after entering a date will move focus to the next focusable element (the guests field), allowing keyboard-only users to continue filling the form without interruption.",
  "functional_risks": [
    "Adding an explicit Tab case could interfere with any custom implementation that expects Tab to trigger datepicker behavior, but the datepicker does not assign any meaning to Tab, so risk is low."
  ],
  "verification_requirements": [
    "After typing a valid date in the check-in field and pressing Tab, the active element must be the guests input.",
    "Arrow keys (←, ↑, →, ↓) must still adjust the date when the picker is open.",
    "Enter and Escape keys must still blur the field when the picker is open.",
    "The picker should still hide appropriately when clicking outside or selecting a date."
  ]
}

